import{_ as l,o as p,c as n,am as o}from"./chunks/framework._FJXuPhs.js";const r=JSON.parse('{"title":"MySQL_常见面试题","description":"","frontmatter":{"title":"MySQL_常见面试题","excerpt":"MySQL_常见面试题","date":"2025-06-20 07:36:12","updated":"2025-06-20 07:36:12"},"headers":[],"relativePath":"数据库/关系型数据库/MySQL/MySQL_常见面试题/index.md","filePath":"数据库/关系型数据库/MySQL/MySQL_常见面试题/index.md","lastUpdated":null}'),s={name:"数据库/关系型数据库/MySQL/MySQL_常见面试题/index.md"};function a(e,i,t,c,u,g){return p(),n("div",null,[...i[0]||(i[0]=[o('<h3 id="面试题" tabindex="-1">面试题 <a class="header-anchor" href="#面试题" aria-label="Permalink to &quot;面试题&quot;">​</a></h3><ul><li>1、如何定位慢查询</li><li>2、SQL 语句执行的很慢，如何分析</li><li>3、索引概念以及索引底层数据结构</li><li>4、聚簇索引和非聚簇索引、回表查询</li><li>5、覆盖索引、超大分页优化</li><li>6、索引创建的原则</li><li>7、什么情况下索引会失效</li><li>8、谈一谈你对 SQL 优化的经验</li><li>9、事务的特性</li><li>10、并发事务问题、隔离级别</li><li>11、undo log 和 redo log 的区别</li><li>12、解释一下 MVCC</li><li>13、主从同步原理</li><li>14、分库分表</li></ul><p>主要面试题：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305190628.png" alt="image.png"></p><h4 id="在-mysql-中-如何定位慢查询" tabindex="-1">在 MySQL 中，如何定位慢查询？ <a class="header-anchor" href="#在-mysql-中-如何定位慢查询" aria-label="Permalink to &quot;在 MySQL 中，如何定位慢查询？&quot;">​</a></h4><h4 id="优化" tabindex="-1">优化 <a class="header-anchor" href="#优化" aria-label="Permalink to &quot;优化&quot;">​</a></h4><h5 id="慢查询" tabindex="-1">慢查询 <a class="header-anchor" href="#慢查询" aria-label="Permalink to &quot;慢查询&quot;">​</a></h5><blockquote><p>在 MySQL 中，如何定位慢查询？</p></blockquote><ul><li>聚合查询</li><li>多表查询</li><li>表数据量过大查询</li><li>深度分页查询</li></ul><p>表象：页面加载过慢、接口压测响应时间过长（超过 1s ）</p><p>方案一、开源工具</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305204256.png" alt="image.png"></p><p>方案二： MySQL 自带慢日志</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305204349.png" alt="image.png"></p><p>总结：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305204413.png" alt="image.png"></p><p>（生产阶段一般不开启慢日志查询）</p><p>开源采用 EXPLAIN 或者 DESC 命令获取 MySQL 如何执行 SELECT 语句的信息</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305205010.png" alt="image.png"></p><p>参数使用</p><ul><li>possible_key</li><li>key</li><li>key_len</li><li>Extra</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305204719.png" alt="image.png"></p><ul><li>type</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305204847.png" alt="image.png"></p><p>总结</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305204938.png" alt="image.png"></p><h5 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引&quot;">​</a></h5><blockquote><p>什么是索引</p></blockquote><p>提高访问效率，索引是某种数据结构组成</p><p>索引(index)是帮助 MySQL 高效获取数据的数据结构 (有序) 。</p><p>在数据之外，数据库系统还维护着满足特定查找算法的数据结构(B+树)，这些数据结构以某种方式引用（指向）数据，这样就可以在这些数据结构上实现高级查找算法，这种数据结构就是索引。</p><blockquote><p>索引的底层结构</p></blockquote><ul><li>目前索引采用的底层结构是 B+ 树</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305211546.png" alt="image.png"></p><blockquote><p>什么是聚簇索引，什么是非聚簇索引</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305212233.png" alt="image.png"></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305212341.png" alt="image.png"></p><blockquote><p>讲一下回表查询</p></blockquote><p>回表查询：通过二级索引找到对应的主键值</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305212500.png" alt="image.png"></p><blockquote><p>知道什么是覆盖索引吗</p></blockquote><p>对查询列有要求，一般是查询的字段和索引字段相同，不同走主键查询那步，直接从索引树上查询出了数据</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305212622.png" alt="image.png"></p><p>你看一下这个例子，主键索引中查询条件是主键的话，直接查询所有数据是话算是覆盖索引，然后如果是二级索引，查询 主键+ 索引 是算覆盖索引查询(索引树上直接查询)</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305212749.png" alt="image.png"></p><p>覆盖索引的基本介绍</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305213542.png" alt="image.png"></p><h6 id="超大分页" tabindex="-1">超大分页 <a class="header-anchor" href="#超大分页" aria-label="Permalink to &quot;超大分页&quot;">​</a></h6><blockquote><p>MySQL 超大分页怎么处理</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305213731.png" alt="image.png"></p><p>提供一种解决思路：通过覆盖索引 + 子查询 形式进行优化 、</p><ul><li>先通过覆盖索引查询出对应的ID，然后通过关联查询，查询出分页数据</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305214250.png" alt="image.png"></p><p>总结</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305214458.png" alt="image.png"></p><h6 id="索引创建原则" tabindex="-1">索引创建原则 <a class="header-anchor" href="#索引创建原则" aria-label="Permalink to &quot;索引创建原则&quot;">​</a></h6><p>回答思路：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305214539.png" alt="image.png"></p><p>主要的一些原则：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305214712.png" alt="image.png"></p><p>索引创建原则有哪些？</p><ul><li><ol><li>数据量较大，且查询比较频繁的表 <strong>重要</strong></li></ol></li><li>2).常作为查询条件、排序、分组的字段 <strong>重要</strong></li><li>3).字段内容区分度高</li><li>4).内容较长，使用前缀索引</li><li>5).尽量联合索引 <strong>重要</strong></li><li>6).要控制索引的数量 <strong>重要</strong></li><li>7).如果索引列不能存储NULL 值，请在创建表时使用NOT NULL 约束它</li></ul><h6 id="索引失效" tabindex="-1">索引失效 <a class="header-anchor" href="#索引失效" aria-label="Permalink to &quot;索引失效&quot;">​</a></h6><p>如何判断索引是否失效：通过 执行计划 explain</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305222045.png" alt="image.png"></p><p>索引失效的一些情况：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305222317.png" alt="image.png"></p><p>理解去记忆一下</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305222354.png" alt="image.png"></p><h4 id="sql-优化" tabindex="-1">SQL 优化 <a class="header-anchor" href="#sql-优化" aria-label="Permalink to &quot;SQL 优化&quot;">​</a></h4><p>谈谈你对 SQL 优化的经验</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305222506.png" alt="image.png"></p><ul><li>主从复制、读写分离</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305222712.png" alt="image.png"></p><p>总结：</p><ul><li>1、表的设计优化，数据类型的选择</li><li>2、索引优化，索引创建原则、</li><li>3、sql语句优化，避免索引失效，避免使用select * ....</li><li>4、主从复制、读写分离，不让数据的写入，影响读操作</li><li>5、分库分表</li></ul><hr><h4 id="其他问题" tabindex="-1">其他问题 <a class="header-anchor" href="#其他问题" aria-label="Permalink to &quot;其他问题&quot;">​</a></h4><h5 id="事务相关" tabindex="-1">事务相关 <a class="header-anchor" href="#事务相关" aria-label="Permalink to &quot;事务相关&quot;">​</a></h5><blockquote><p>事务的特性</p></blockquote><p>事务：事务是一组操作的集合，它是一个不可分割的工作单位，事务会把所有的操作作为一个整体一起向系 统提交或撤销操作请求，即这些操作要么同时成功，要么同时失败。</p><p>ACID是什么？可以详细说一下吗？</p><ul><li>原子性(Atomicity):事务是不可分割的最小操作单元，要么全部成功，要么全部失败。</li><li>一致性(Consistency):事务完成时，必须使所有的数据都保持一致状态。</li><li>隔离性(Isolation)：数据库系统提供的隔离机制，保证事务在不受外部并发操作影响的独立环境下运行。</li><li>持久性(Durability)：事务一旦提交或回滚，它对数据库中的数据的改变就是永久的。</li></ul><p>讲述这种题目的适合最好结合一下实际案例来讲述一下，让面试官觉得你讲的和其他人有所不同</p><p>示例：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305223200.png" alt="image.png"></p><hr><blockquote><p>并发事务带来哪些问题？怎么解决这些问题呢？MySQL 的隔离级别是？</p></blockquote><ul><li>并发事务问题：脏读、不可重复读、幻读</li><li>隔离级别：读未提交、读已提交、可重复读、串行化</li></ul><p>并发事务问题</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305223338.png" alt="image.png"></p><p>怎么解决并发事务的问题？</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305223402.png" alt="image.png"></p><p>注意：事务隔离级别越高，数据越安全，但是性能越低。</p><p>总结：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305223512.png" alt="image.png"></p><h5 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h5><blockquote><p>undo log 和 redo log 的区别？</p></blockquote><p>先引入一个概念：即缓存池和数据页，数据页是磁盘中实际存储的数据，但一般数据加载的时候会先从内存中到磁盘，这个内存的区域叫做缓冲池。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305223637.png" alt="image.png"></p><p>服务宕机的时候，数据如何保证不丢失，是由于日志的存在。</p><ul><li>redo log：</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305231922.png" alt="image.png"></p><ul><li>undo log</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305232004.png" alt="image.png"></p><p>总结：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305232037.png" alt="image.png"></p><hr><p>后面还有几道，明天再看一下</p><ul><li>12、解释一下 MVCC</li><li>13、主从同步原理</li><li>14、分库分表</li></ul><hr>',111)])])}const m=l(s,[["render",a]]);export{r as __pageData,m as default};
